128	// attachOutcomes marks each test node with what happened, and carries a
129	// failure onto every shadowed node on that test's path to a source.
130	func attachOutcomes(a *report.Analysis, cands []shadow.Candidate, v graph.Verdict) {
131		failed := map[string]bool{}
132		for _, id := range v.NewlyFailing {
133			failed[id] = true
134		}
135		// A test that was already failing before the change is still failing. It
136		// is not a crack, because this change did not break it, but calling it a
137		// pass would be a lie.
138		preExisting := map[string]bool{}
139		for _, id := range v.PreExisting {
140			preExisting[id] = true
141		}
142		for _, c := range cands {
143			switch {
144			case failed[c.ID], preExisting[c.ID]:
145				c.Node.Result = shadow.OutcomeFail
146			case v.Degraded:
147				// Without per-test ids there is no per-test outcome to report.
148				c.Node.Result = shadow.OutcomeNotRun
149			default:
150				c.Node.Result = shadow.OutcomePass
151			}
152		}
153	
154		// A failing probe is evidence about every shadowed node it passes through.
155		for _, c := range cands {
156			if !failed[c.ID] {
157				continue
158			}
159			for _, n := range a.Nodes {
160				if !n.Shadowed() || n.Symbol.ID == c.Node.Symbol.ID {
161					continue
162				}
163				if onPath(n.Symbol.ID, c.Node.Path) {
164					n.Tests = append(n.Tests, shadow.TestRef{ID: c.ID, Symbol: c.Node.Symbol.ID, Outcome: shadow.OutcomeFail})
165				}
166			}
167		}
168	}
169	
170	func onPath(id string, path []string) bool {
171		for _, p := range path {
172			if p == id {
173				return true
174			}
175		}
176		return false
177	}
178	
179	// scrubAll puts the verify commands through the same scrubber as every other
180	// recorded command.
181	//
182	// They used to be appended raw, so a report carried the absolute path of the
183	// worktree the tests ran in. Every other command in the list was scrubbed,
184	// which is why it went unnoticed until a real report was committed and the
185	// artifacts test read it.
186	func scrubAll(st *pipelineState, cmds []string) []string {
187		if st == nil || st.Scrub == nil {
188			return cmds
189		}
190		out := make([]string, 0, len(cmds))
191		for _, c := range cmds {
192			out = append(out, st.Scrub.Clean(c))
193		}
194		return out
195	}
