func glyph(s shadow.State, o TableOptions) string {
	if o.UTF8 {
		return s.Glyph()
	}
	return s.ASCII()
}

func glyphColoured(s shadow.State, o TableOptions) string {
	g := glyph(s, o)
	switch s {
	case shadow.Umbra:
		return colour(o, ansiRed, g)
	case shadow.Penumbra:
		return colour(o, ansiYellow, g)
	case shadow.Lit:
		return colour(o, ansiGreen, g)
	}
	return g
}

func colour(o TableOptions, code, s string) string {
	if !o.Colour {
		return s
	}
	return code + s + ansiReset
}

func dim(o TableOptions, s string) string { return colour(o, ansiDim, s) }

func trunc(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	if n <= 3 {
		return string(r[:n])
	}
	return "..." + string(r[len(r)-(n-3):])
}

func shortSHA(s string) string {
	if len(s) > 7 {
		return s[:7]
	}
	if s == "" {
		return "(no commit)"
	}

func probeText(a *Analysis) string {
	if a.Run == "none" {
		return "probes not run"
	}
	if len(a.Execution.Selected) == 0 {
		return "no probe reaches the shadow"
	}
	return fmt.Sprintf("%d probes, %d cracked", len(a.Execution.Selected), len(a.Execution.CrackedProbes()))
}

